        TestClass.teardown_called = False
    """
    )

    # Get the Class collector
    items = pytester.getitems("""
        import pytest

        class TestClass:
            @classmethod
            def setup_class(cls):
                cls.setup_called = True

            @classmethod
            def teardown_class(cls):
                cls.teardown_called = True

            def test_method(self):
                assert self.setup_called
    """)

    # Find the Class collector
    class_item = None
    for item in items:
        if hasattr(item, 'cls') and item.cls.__name__ == 'TestClass':
            class_item = item.getparent(pytest.Class)
            break

    assert class_item is not None

    # Check that the fixture was injected
    assert hasattr(class_item.obj, '__pytest_setup_class')

    # Run the test to verify the setup method is called
    result = pytester.runpytest("-v")
    result.stdout.fnmatch_lines(["*1 passed*"])
