def test_idmaker_with_callable_ids(pytester: Pytester) -> None:
    """Test idmaker with callable ids parameter."""
    import functools

    def make_id(val):
        if isinstance(val, functools.partial):
            return val.func.__name__ + "_partial"
        return str(val)

    def func():
        pass

    partial_func = functools.partial(func, 1)
    parametersets = [pytest.param(1), pytest.param(partial_func)]
    argnames = ["arg"]
    ids = idmaker(argnames, parametersets, idfn=make_id)
    assert ids == ["1", "func_partial"]
