@isolate_apps('check_framework', attr_name='apps')
@override_system_checks([checks.model_checks.check_all_models])
class FieldNameClashTests(SimpleTestCase):

    def test_field_name_clash_with_parent_inheritance(self):
        """Test that field name clashes between parent and child models are detected."""
        class ParentModel(models.Model):
            name = models.CharField(max_length=100)

        class ChildModel(ParentModel):
            name = models.CharField(max_length=200)  # Clashing field name

        self.assertEqual(ChildModel.check(), [
            Error(
                "The field 'name' clashes with the field 'name' from model "
                "'check_framework.ParentModel'.",
                obj=ChildModel._meta.get_field('name'),
                id='models.E006',
            )
        ])

    def test_field_attname_clash_with_parent(self):
        """Test that field attname clashes with parent fields are detected."""
        class ParentModel(models.Model):
            name = models.CharField(max_length=100)

        class ChildModel(ParentModel):
            # Create a field that would clash with parent's attname
            name_id = models.IntegerField()  # Assuming parent has a related field that uses name_id

        # We need to simulate the clash more carefully
        # Let's create a foreign key in parent and then clash with attname in child
        class ParentWithFK(models.Model):
            related = models.ForeignKey('self', on_delete=models.CASCADE)

        class ChildWithAttnameClash(ParentWithFK):
            related_id = models.CharField(max_length=100)  # This clashes with parent's related_id attname

        self.assertEqual(ChildWithAttnameClash.check(), [
            Error(
                "The field 'related_id' clashes with the field 'related_id' "
                "from model 'check_framework.ParentWithFK'.",
                obj=ChildWithAttnameClash._meta.get_field('related_id'),
                id='models.E006',
            )
        ])

    def test_no_clash_different_fields(self):
        """Test that non-clashing fields don't generate errors."""
        class ParentModel(models.Model):
            name = models.CharField(max_length=100)

        class ChildModel(ParentModel):
            title = models.CharField(max_length=200)  # Different field name

        self.assertEqual(ChildModel.check(), [])

    def test_id_field_clash_special_case(self):
        """Test the special case handling for 'id' field clashes."""
        class ModelWithCustomId(models.Model):
            id = models.CharField(max_length=100)  # Non-PK id field

        # Should generate E004 error for invalid id field, not E006
        errors = ModelWithCustomId.check()
        self.assertTrue(any(error.id == 'models.E004' for error in errors))
