def test_itermonomials_min_degrees_total_degree():
    # Test case for total degree with min_degree > 0
    assert set(itermonomials([x, y], 3, 2)) == {x**2, x*y, y**2, x**3, x**2*y, x*y**2, y**3}

    # Test case for total degree with min_degree = max_degree
    assert set(itermonomials([x, y], 2, 2)) == {x**2, x*y, y**2}

    # Test case for total degree with min_degree > max_degree (should be empty)
    assert set(itermonomials([x, y], 1, 2)) == set()

    # Test case for single variable with min_degree > 0
    assert set(itermonomials([x], 3, 2)) == {x**2, x**3}

    # Test case for single variable with min_degree = max_degree
    assert set(itermonomials([x], 2, 2)) == {x**2}

    # Test case with non-commutative variables and min_degree > 0
    i, j = symbols('i j', commutative=False)
    assert set(itermonomials([i, j], 2, 1)) == {i, j, i**2, i*j, j*i, j**2}
