def test_add_entry_with_subword(app):
    """Test add_entry function with subword parameter."""
    text = (".. index:: single: main entry; sub entry\n"
            ".. index:: pair: primary; secondary\n")
    restructuredtext.parse(app, text)

    # Mock the builder to avoid actual URI generation
    class MockBuilder:
        def get_relative_uri(self, from_, to):
            return f"#{to}"

    builder = MockBuilder()
    index_entries = IndexEntries(app.env)

    # Call create_index which will internally use add_entry
    index = index_entries.create_index(builder)

    # Verify that sub-entries are properly created
    # Look for the main entry that should have sub-entries
    found_main_with_sub = False
    for letter, entries in index:
        for entry_name, (targets, subentries, key) in entries:
            if entry_name == 'main entry' and subentries:
                # Check if sub entry exists
                for subentry_name, subentry_data in subentries:
                    if subentry_name == 'sub entry':
                        found_main_with_sub = True
                        break
            elif entry_name == 'primary' and subentries:
                # Check pair entries too
                for subentry_name, subentry_data in subentries:
                    if subentry_name == 'secondary':
                        found_main_with_sub = True
                        break

    assert found_main_with_sub, "Sub-entries were not properly added"


@pytest.mark.sphinx('dummy', freshenv=True)
def test_add_entry_link_handling(app):
    """Test add_entry function's link parameter handling."""
    text = (".. index:: see: source; target\n"
            ".. index:: single: linked entry\n")
    restructuredtext.parse(app, text)

    class MockBuilder:
        def get_relative_uri(self, from_, to):
            # Simulate NoUri exception for certain cases
            if to == 'no-uri-case':
                from sphinx.errors import NoUri
                raise NoUri()
            return f"#{to}"

    builder = MockBuilder()
    index_entries = IndexEntries(app.env)

    # Test normal case
    index = index_entries.create_index(builder)

    # Verify see entry has no links (link=False)
    see_entry_found = False
    single_entry_found = False

    for letter, entries in index:
        for entry_name, (targets, subentries, key) in entries:
            if 'see' in entry_name and 'target' in str(subentries):
                # This should be a see entry with no actual links
                see_entry_found = True
            elif entry_name == 'linked entry':
                single_entry_found = True
                # This should have links
                assert len(targets) > 0

    assert see_entry_found, "See entry was not found"
    assert single_entry_found, "Single entry was not found"
