class ModelIterableTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.countries = [
            Country.objects.create(name="United States of America", iso_two_letter="US"),
            Country.objects.create(name="The Netherlands", iso_two_letter="NL"),
            Country.objects.create(name="Germany", iso_two_letter="DE"),
            Country.objects.create(name="Czech Republic", iso_two_letter="CZ"),
        ]

    def test_model_iterable_basic(self):
        """Test that ModelIterable returns model instances."""
        queryset = Country.objects.all()
        iterable = ModelIterable(queryset)
        results = list(iterable)
        self.assertEqual(len(results), 4)
        for result in results:
            self.assertIsInstance(result, Country)
        # Check that the results match the created countries
        result_names = {country.name for country in results}
        expected_names = {country.name for country in self.countries}
        self.assertEqual(result_names, expected_names)

    def test_model_iterable_with_annotations(self):
        """Test that ModelIterable properly handles annotated fields."""
        queryset = Country.objects.annotate(lower_name=Lower("name"))
        iterable = ModelIterable(queryset)
        results = list(iterable)
        self.assertEqual(len(results), 4)
        for result in results:
            self.assertIsInstance(result, Country)
            self.assertTrue(hasattr(result, 'lower_name'))

    def test_model_iterable_with_related_objects(self):
        """Test that ModelIterable properly handles known related objects."""
        # Create a related model instance
        related_model = RelatedModel.objects.create(country=self.countries[0])

        # Create a queryset with known related objects
        queryset = Country.objects.filter(pk=self.countries[0].pk)
        queryset._known_related_objects = {
            RelatedModel._meta.get_field('country'): {
                related_model.pk: related_model
            }
        }

        iterable = ModelIterable(queryset)
        results = list(iterable)
        self.assertEqual(len(results), 1)
        country = results[0]
        self.assertIsInstance(country, Country)
        # Check that the related object is properly set
        self.assertEqual(country.relatedmodel, related_model)
