class DeferredAttributeTests(SimpleTestCase):
    def test___get__(self):
        # Define a mock instance and class to simulate the behavior
        class MockField:
            attname = 'test_field'

        class MockInstance:
            def __init__(self):
                self.__dict__ = {}
                self._meta = MockMeta()

            def refresh_from_db(self, fields=None):
                self.__dict__['test_field'] = 'loaded_value'

        class MockMeta:
            def get_ancestor_link(self, model):
                return None

        # Create a DeferredAttribute instance
        field = MockField()
        deferred_attr = DeferredAttribute(field)

        # Create a mock instance
        instance = MockInstance()

        # Access the deferred attribute
        value = deferred_attr.__get__(instance)

        # Check that the value was loaded correctly
        self.assertEqual(value, 'loaded_value')
        self.assertIn('test_field', instance.__dict__)
        self.assertEqual(instance.__dict__['test_field'], 'loaded_value')

    def test___get__without_instance(self):
        # Define a mock field
        class MockField:
            attname = 'test_field'

        # Create a DeferredAttribute instance
        field = MockField()
        deferred_attr = DeferredAttribute(field)

        # Access the deferred attribute without an instance (class access)
        value = deferred_attr.__get__(None)

        # Should return the DeferredAttribute instance itself
        self.assertIs(value, deferred_attr)

    def test___get__with_parent_chain(self):
        # Define mock classes to simulate model inheritance
        class ParentModel:
            pass

        class ChildModel(ParentModel):
            pass

        class MockField:
            attname = 'test_field'
            primary_key = True
            model = ParentModel

        class MockInstance:
            def __init__(self):
                self.__dict__ = {'parent_link_field': 'parent_value'}
                self._meta = MockMeta()

            def refresh_from_db(self, fields=None):
                pass

        class MockMeta:
            def get_ancestor_link(self, model):
                if model == ParentModel:
                    return type('link_field', (), {'attname': 'parent_link_field'})()
                return None

        # Create a DeferredAttribute instance
        field = MockField()
        deferred_attr = DeferredAttribute(field)

        # Create a mock instance
        instance = MockInstance()

        # Access the deferred attribute
        value = deferred_attr.__get__(instance)

        # Check that the value was fetched from the parent chain
        self.assertEqual(value, 'parent_value')
        self.assertIn('test_field', instance.__dict__)
        self.assertEqual(instance.__dict__['test_field'], 'parent_value')
