def test_repr_failure_py_exception_chain_repr_integration(testdir):
    """Test that _repr_failure_py returns an ExceptionChainRepr when applicable."""
    # Create a test file that will cause a chained exception during collection
    testdir.makepyfile(
        """
        import pytest

        @pytest.fixture
        def fixture_with_chained_exception():
            try:
                raise ValueError("initial error")
            except ValueError as e:
                raise RuntimeError("chained error") from e

        def test_something(fixture_with_chained_exception):
            pass
        """
    )

    # Collect the items
    items = testdir.getitems("")
    item = items[0]

    # Simulate a failure scenario that would result in an ExceptionChainRepr
    try:
        try:
            raise ValueError("initial error")
        except ValueError as e:
            raise RuntimeError("chained error") from e
    except RuntimeError as e:
        exc_info = pytest.ExceptionInfo.from_current()

        # Call _repr_failure_py
        result = item._repr_failure_py(exc_info)

        # Should return an ExceptionChainRepr
        assert isinstance(result, pytest.ExceptionChainRepr)
