def test_pytest_runtest_makereport_xfail_with_reason(testdir):
    """Test that pytest_runtest_makereport properly handles xfail marks with reasons."""
    testdir.makepyfile(
        """
        import pytest

        @pytest.mark.xfail(reason="this is an expected failure")
        def test_expected_failure():
            assert False

        @pytest.mark.xfail(reason="this is an expected failure")
        def test_unexpected_pass():
            assert True
    """
    )
    result = testdir.runpytest("-rxX")
    result.stdout.fnmatch_lines(
        [
            "*XFAIL*test_expected_failure*",
            "*this is an expected failure*",
            "*XPASS*test_unexpected_pass*",
            "*this is an expected failure*",
        ]
    )
