def test_canonical_variables():
    x, i0, i1 = symbols('x _:2')
    assert Integral(x, (x, x + 1)).canonical_variables == {x: i0}
    assert Integral(x, (x, x + i0)).canonical_variables == {x: i1}
    # Test case for expression with no bound symbols
    assert Basic().canonical_variables == {}
    # Test case for Lambda with bound symbols
    assert Lambda(x, x + 1).canonical_variables == {x: i0}
    # Test case for Lambda with multiple bound symbols
    y = symbols('y')
    assert Lambda((x, y), x + y).canonical_variables == {x: i0, y: i1}
